import java.text.Normalizer;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * A filter over the customer list: a name search and a set of statuses.
 *
 * <p>Both parts are matched by {@link CustomerRepository} so that the grid
 * stays lazily loaded: only matching rows are ever paged or counted.
 *
 * @param name      free text; split on whitespace into terms that must all
 *                  appear (case- and accent-insensitively) in the first name
 *                  or the last name. Blank matches every customer.
 * @param statuses  statuses to restrict to; empty matches every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
    }

    /** Whether the given customer satisfies both the name and status filters. */
    public boolean matches(Customer customer) {
        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
            return false;
        }
        List<String> terms = nameTerms();
        if (terms.isEmpty()) {
            return true;
        }
        String first = normalize(customer.firstName());
        String last = normalize(customer.lastName());
        for (String term : terms) {
            if (!first.contains(term) && !last.contains(term)) {
                return false;
            }
        }
        return true;
    }

    private List<String> nameTerms() {
        String trimmed = name.trim();
        if (trimmed.isEmpty()) {
            return List.of();
        }
        return Arrays.stream(trimmed.split("\\s+")).map(CustomerFilter::normalize).toList();
    }

    private static String normalize(String s) {
        return Normalizer.normalize(s, Normalizer.Form.NFD)
                .replaceAll("\\p{M}", "")
                .toLowerCase(Locale.ROOT);
    }
}
