/**
 * Lists customers in a lazily loaded {@link Grid}, with a filter bar that
 * narrows the list by name and status.
 *
 * <p>The grid never holds the whole data set: it asks the backend for one page
 * at a time and asks separately for the total row count, and both the paging
 * and the counting take the current filter into account.
 *
 * <p>The filter is reflected in the URL's {@code name} and {@code status}
 * query parameters, so a narrowed list can be bookmarked or shared.
 */
@Route("")
@PageTitle("Customers")
public class CustomerListView extends VerticalLayout implements BeforeEnterObserver {

    private final CustomerService customerService;
    private final Grid<Customer> grid = new Grid<>(Customer.class, false);
    private final TextField nameFilter = new TextField();
    private final MultiSelectComboBox<CustomerStatus> statusFilter = new MultiSelectComboBox<>("Status");
    private final Span summary = new Span();

    private CustomerFilter filter = CustomerFilter.EMPTY;
    private final int totalCustomers;

    public CustomerListView(CustomerService customerService) {
        this.customerService = customerService;
        this.totalCustomers = customerService.count(CustomerFilter.EMPTY);

        setSizeFull();

        configureFilterBar();
        configureGrid();
        updateSummary(totalCustomers);

        add(new H2("Customers"), new HorizontalLayout(nameFilter, statusFilter), summary, grid);
    }

    @Override
    public void beforeEnter(BeforeEnterEvent event) {
        QueryParameters queryParameters = event.getLocation().getQueryParameters();
        String name = queryParameters.getSingleParameter("name").orElse("");
        Set<CustomerStatus> statuses = queryParameters.getSingleParameter("status")
                .map(CustomerListView::parseStatuses)
                .orElse(Set.of());

        nameFilter.setValue(name);
        statusFilter.setValue(statuses);
    }

