+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+/**
+ * Throwaway real-browser check, exercising things Karibu cannot see: the
+ * address bar and how many backend queries typing costs.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Test
+    void typingNarrowsGridAndUpdatesUrlWithoutQueryingPerKeystroke() {
+        TextFieldElement nameFilter = TextFieldElement.getByLabel(page, "Filter by name");
+
+        queryLog.clear();
+        nameFilter.getInputLocator().pressSequentially("Virtanen", new Locator.PressSequentiallyOptions().setDelay(30));
+        page.waitForTimeout(1000);
+
+        int countQueriesAfterTyping = queryLog.countQueries().size();
+        System.out.println("Count queries after typing 'Virtanen': " + countQueriesAfterTyping);
+        assertTrue(countQueriesAfterTyping <= 2,
+                "typing a nine-letter name cost " + countQueriesAfterTyping + " backend count queries");
+
+        assertTrue(page.url().contains("name=Virtanen"), "address bar was: " + page.url());
+
+        GridElement grid = GridElement.get(page);
+        assertEquals(15, grid.getTotalRowCount());
+    }
+
+    @Test
+    void statusSelectionUpdatesUrl() {
+        MultiSelectComboBoxElement statusFilter = MultiSelectComboBoxElement.getByLabel(page, "Status");
+        statusFilter.selectItem("ACTIVE");
+        statusFilter.selectItem("CLOSED");
+        page.waitForTimeout(500);
+
+        assertTrue(page.url().contains("status=ACTIVE%2CCLOSED") || page.url().contains("status=ACTIVE,CLOSED"),
+                "address bar was: " + page.url());
+    }
+
+    @Test
+    void openingWithQueryParametersAppliesTheFilter() {
+        page.navigate(getUrl() + "/?name=vir&status=ACTIVE,CLOSED");
+        page.waitForTimeout(500);
+
+        TextFieldElement nameFilter = TextFieldElement.getByLabel(page, "Filter by name");
+        assertEquals("vir", nameFilter.getValue());
+
+        GridElement grid = GridElement.get(page);
+        assertEquals(10, grid.getTotalRowCount());
+    }
+}
